192	      }
193	      out.set(p.id, dues.reduce((sum, d) => sum + d, 0));
194	    }
195	    return out;
196	  });
197	  /** Each person's overdue claims, by person id: how many of their counting claims are overdue
198	   *  (OPEN with the due-by before the sheet's today), and the dues they show in cents (n/a ones skipped). */
199	  private readonly overdueByPerson = computed(() => {
200	    const out = new Map<number, { count: number; cents: number }>();
201	    const floor = cents(this.session.floor());
202	    const late = this.lateness();
203	    for (const p of this.people()) {
204	      const overdueClaims = this.claimsOf(p.id).filter(this.countsLive()).filter((c) => overdue(c, late.terms, late.today));
205	      out.set(p.id, {
206	        count: overdueClaims.length,
207	        cents: overdueClaims.reduce((sum, c) => sum + (this.claimDueCents(p, c, floor, late) ?? 0), 0),
208	      });
209	    }
210	    return out;
211	  });
212	  protected readonly overdueCount = computed(() =>
213	    [...this.overdueByPerson().values()].reduce((sum, o) => sum + o.count, 0));
214	  protected readonly overdueTotal = computed(() =>
215	    money([...this.overdueByPerson().values()].reduce((sum, o) => sum + o.cents, 0)));
216	  protected readonly money = money;
217	  /** The sheet's periods, by from-date. */
218	  protected readonly periods = signal<Period[]>([]);
219	  /** Each period's due-total in cents, by period id: the dues (n/a ones skipped) of the OPEN and
220	   *  SETTLED claims whose date falls in it (a held person's OPEN ones left out). */
221	  protected readonly dueByPeriod = computed(() => {
222	    const out = new Map<number, number>();
223	    const floor = cents(this.session.floor());
224	    const late = this.lateness();
225	    for (const p of this.people()) {
226	      for (const c of this.claimsOf(p.id).filter(this.countsLive())) {
227	        const period = periodOn(this.periods(), c.date);
228	        if (period === null) continue;
229	        out.set(period.id, (out.get(period.id) ?? 0) + (this.claimDueCents(p, c, floor, late) ?? 0));
230	      }
231	    }
232	    return out;
233	  });
234	  /** Each person as the summary counts them: grade today, whether retired (as the list hides them), due-total. */
235	  protected readonly summaryPeople = computed<SummaryPerson[]>(() => {
236	    const dues = this.dueByPerson();
237	    return this.people().map((p) => ({ grade: this.gradeOf(p), retired: p.retiredFrom !== null, due: dues.get(p.id) ?? null }));
238	  });
239	  /** The names of the people on the sheet, by person id (retired ones too). */
240	  private readonly namesById = computed(() => new Map(this.people().map((p) => [p.id, p.name])));
241	  /** Everyone's due-total added up, skipping n/a. */
242	  protected readonly dueTotal = computed(() =>
243	    money([...this.dueByPerson().values()].reduce<number>((sum, d) => sum + (d ?? 0), 0)));
244	  protected readonly claimedTotal = computed(() =>
245	    money(this.people().reduce((sum, p) => sum + (this.byPerson().get(p.id)?.cents ?? 0), 0)));
246	  protected readonly editingId = signal<number | null>(null);
247	  /** The version of the person the open editor loaded. */
248	  private editingVersion = 0;
249	  /** Whether a submit is waiting for its answer; a second submit meanwhile is ignored. */
250	  private submitting = false;
251	  protected readonly error = signal<string | null>(null);
252	  /** The error of each person's last refused row action, by person id. */
253	  protected readonly rowErrors = signal<Record<number, string>>({});
254	  /** The error of each person's last refused patron, by person id. */
255	  protected readonly patronErrors = signal<Record<number, string>>({});
256	
257	  protected readonly form = new FormGroup({
258	    name: new FormControl('', { nonNullable: true, validators: Validators.required }),
259	    grade: new FormControl<string>('A', { nonNullable: true, validators: Validators.required }),
260	    /** On an edit, the date the grade is in force from; blank takes the sheet's today. */
261	    gradeFrom: new FormControl('', { nonNullable: true }),
262	  });
263	
264	  /** The quick-add bar: a name and an amount make a DRAFT claim for that person. */
265	  protected readonly quickForm = new FormGroup({
266	    name: new FormControl('', { nonNullable: true }),
267	    amount: new FormControl('', { nonNullable: true }),
268	  });
269	  protected readonly quickError = signal<string | null>(null);
270	  private quickAdding = false;
271	
272	  /** Guards against a slower, older read landing over a newer one. */
273	  private readSeq = 0;
274	
275	  constructor() {
276	    this.form.valueChanges.subscribe(() => this.error.set(null));
277	    this.quickForm.valueChanges.subscribe(() => this.quickError.set(null));
278	    effect(() => {
279	      const id = this.session.sheetId();
280	      this.session.loads();
281	      untracked(() => {
282	        this.reset();
283	        this.rowErrors.set({});
284	        this.patronErrors.set({});
285	        this.quickForm.reset({ name: '', amount: '' });
286	        this.quickError.set(null);
287	        this.people.set([]);
288	        this.claims.set([]);
289	        this.rates.set([]);
290	        this.periods.set([]);
291	        if (id) void this.read(id);
292	      });
293	    });
294	  }
295	
296	  protected edit(p: Person): void {
297	    this.error.set(null);
298	    this.editingId.set(p.id);
299	    this.editingVersion = p.version;
300	    this.form.setValue({ name: p.name, grade: this.gradeOf(p), gradeFrom: '' });
301	  }
302	
303	  protected claimsOf(personId: number): Claim[] {
304	    return this.byPerson().get(personId)?.claims ?? [];
305	  }
306	
307	  protected overdueOf(personId: number): { count: number; cents: number } {
308	    return this.overdueByPerson().get(personId) ?? { count: 0, cents: 0 };
309	  }
310	
311	  protected claimedBy(personId: number): string {
312	    return money(this.byPerson().get(personId)?.cents ?? 0);
313	  }
314	
315	  /** The grade the person shows: the one in force on the sheet's today. */
316	  protected gradeOf(p: Person): string {
317	    return gradeOn(p.grades, this.session.today());
318	  }
319	
320	  /** A claim's due in cents, at the rate of the person's grade in force on the claim's date. */
321	  private claimDueCents(p: Person, c: Claim, floor: number, late: Lateness): number | null {
322	    return claimDueCents(this.ratesOf(gradeOn(p.grades, c.date)), c, floor, late,
323	      roundsHalfUp(c, this.claimsOf(p.id), this.session.policyDate(), late.today));
324	  }
325	
326	  /** Every rate the sheet has for a grade. */
327	  protected ratesOf(grade: string): Rate[] {
328	    return this.rates().filter((r) => r.grade === grade);
329	  }
330	
331	  protected dueOf(p: Person): string {
332	    const due = this.dueByPerson().get(p.id);
333	    return due === null || due === undefined ? 'n/a' : money(due);
334	  }
335	
336	  /** The person's patrons' names, sorted, comma and space separated. */
337	  protected patronNamesOf(p: Person): string {
338	    const names = this.namesById();
339	    return p.patronIds.map((id) => names.get(id) ?? '').filter((n) => n).sort().join(', ');
340	  }
341	
342	  /** The person's patrons' due-totals added up, skipping n/a; 0.00 with no patrons. */
343	  protected backingOf(p: Person): string {
344	    const dues = this.dueByPerson();
345	    return money(p.patronIds.reduce((sum, id) => sum + (dues.get(id) ?? 0), 0));
346	  }
347	
348	  /** The people the person may name as a patron: everyone else on the sheet. */
349	  protected patronChoicesFor(p: Person): Person[] {
350	    return this.people().filter((o) => o.id !== p.id);
351	  }
352	
353	  /** Name another person as the person's patron; the row then shows them among its patrons. */
354	  protected async addPatron(p: Person, patronId: string): Promise<void> {
355	    this.clearRowError(p.id);
356	    const sheetId = this.session.sheetId();
357	    if (!sheetId) return;
358	    if (!patronId) {
359	      this.patronErrors.update((errs) => ({ ...errs, [p.id]: 'Choose a patron.' }));
360	      return;
361	    }
362	    try {
363	      const saved = await this.api.addPatron(sheetId, p.id, Number(patronId));
364	      if (this.session.sheetId() === sheetId) this.taken(saved);
365	    } catch (e) {
366	      this.patronErrors.update((errs) => ({ ...errs, [p.id]: patronError(e) }));
367	    }
368	  }
369	
370	  /** The last statement's due-total: blank with none, n/a when it was n/a. */
371	  protected statedTotalOf(p: Person): string {
372	    return p.statementCount === 0 ? '' : (p.statedTotal ?? 'n/a');
373	  }
374	
375	  /** Take a statement of a person; the row then shows it and their claims as bound now. */
376	  protected async statement(p: Person): Promise<void> {
377	    this.clearRowError(p.id);
378	    const sheetId = this.session.sheetId();
379	    if (!sheetId) return;
380	    try {
381	      const taken = await this.api.statement(sheetId, p.id);
382	      if (this.session.sheetId() !== sheetId) return;
383	      this.taken(taken.person);
384	      this.claims.update((cs) => [...cs.filter((c) => c.personId !== p.id), ...taken.claims].sort((a, b) => b.id - a.id));
385	    } catch (e) {
386	      this.rowErrors.update((errs) => ({ ...errs, [p.id]: statementError(e) }));
387	    }
388	  }
389	
390	  /** Retire a person from a date (blank: the sheet's today); the row then shows them retired. */
391	  protected async retire(p: Person, from: string): Promise<void> {
392	    this.clearRowError(p.id);
393	    const sheetId = this.session.sheetId();
394	    if (!sheetId) return;
395	    try {
396	      const retired = await this.api.retire(sheetId, p.id, from.trim());
397	      if (this.session.sheetId() === sheetId) this.taken(retired);
398	    } catch (e) {
399	      this.rowErrors.update((errs) => ({ ...errs, [p.id]: retireError(e) }));
400	    }
401	  }
402	
403	  /** Put a person on hold, or take them off it when held; the row then shows the new state. */
404	  protected async hold(p: Person): Promise<void> {
405	    this.clearRowError(p.id);
406	    const sheetId = this.session.sheetId();
407	    if (!sheetId) return;
408	    try {
409	      const saved = await this.api.hold(sheetId, p.id, !p.held);
410	      if (this.session.sheetId() === sheetId) this.taken(saved);
411	    } catch (e) {
412	      this.rowErrors.update((errs) => ({ ...errs, [p.id]: holdError(e) }));
413	    }
414	  }
415	
416	  protected clearRowError(id: number): void {
417	    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
418	    this.patronErrors.update(({ [id]: _, ...rest }) => rest);
419	  }
420	
421	  /** Take in a rate just set, in place of the grade's old one for the same from-date. */
422	  protected rateSaved(rate: Rate): void {
423	    this.rates.update((rs) => [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
424	  }
425	
426	  /** Take in a period just added or closed, in its place by from-date. */
427	  protected periodSaved(period: Period): void {
428	    this.periods.update((ps) => [...ps.filter((p) => p.id !== period.id), period].sort((a, b) => a.from.localeCompare(b.from)));
429	  }
430	
431	  /** Take in a claim just added (listed first, as the newest) or saved (in its place). */
432	  protected claimSaved(claim: Claim): void {
433	    this.claims.update((cs) => cs.some((c) => c.id === claim.id)
434	      ? cs.map((c) => (c.id === claim.id ? claim : c))
435	      : [claim, ...cs].sort((a, b) => b.id - a.id));
436	  }
437	
438	  protected cancel(): void {
439	    this.reset();
440	  }
441	
442	  protected async submit(): Promise<void> {
443	    if (this.submitting) return;
444	    this.error.set(null);
445	    const sheetId = this.session.sheetId();
446	    if (!sheetId) return;
447	    const value = this.form.getRawValue();
448	    if (!value.name.trim()) {
449	      this.error.set('Enter a name.');
450	      return;
451	    }
452	    if (!(GRADES as readonly string[]).includes(value.grade)) {
453	      this.error.set('Choose a grade.');
454	      return;
455	    }
456	    const editing = this.editingId();
457	    this.submitting = true;
458	    try {
459	      if (editing === null) {
460	        const added = await this.api.add(sheetId, { name: value.name, grade: value.grade });
461	        if (this.session.sheetId() === sheetId) this.people.update((ps) => [...ps, added]);
462	      } else {
463	        const saved = await this.api.update(sheetId, editing,
464	          { ...value, gradeFrom: value.gradeFrom.trim() || null, version: this.editingVersion });
465	        if (this.session.sheetId() === sheetId) this.taken(saved);
466	      }
467	      this.reset();
468	    } catch (e) {
469	      if (editing !== null && isStale(e)) await this.reloadEditing(sheetId, editing);
470	      this.error.set(personError(e));
471	    } finally {
472	      this.submitting = false;
473	    }
474	  }
475	
476	  /** Quick-add a DRAFT claim by name; the person is added first (grade A) when new. */
477	  protected async quickAdd(): Promise<void> {
478	    if (this.quickAdding) return;
479	    this.quickError.set(null);
480	    const sheetId = this.session.sheetId();
481	    if (!sheetId) return;
482	    const value = this.quickForm.getRawValue();
483	    const amount = value.amount.trim();
484	    if (!value.name.trim()) {
485	      this.quickError.set('Enter a name.');
486	      return;
487	    }
488	    if (!AMOUNT_PATTERN.test(amount)) {
489	      this.quickError.set('Enter an amount of 0.00 or more with up to two decimals.');
490	      return;
491	    }
492	    this.quickAdding = true;
493	    try {
494	      const added = await this.claimsApi.quickAdd(sheetId, { name: value.name, amount });
495	      if (this.session.sheetId() !== sheetId) return;
496	      if (added.personAdded) this.people.update((ps) => [...ps.filter((p) => p.id !== added.person.id), added.person]);
497	      else this.taken(added.person);
498	      this.claimSaved(added.claim);
499	      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
500	    } catch (e) {
501	      this.quickError.set(quickAddError(e));
502	    } finally {
503	      this.quickAdding = false;
504	    }
505	  }
506	
507	  /** Take in a person as the store now holds them, in place of the old row. */
508	  private taken(person: Person): void {
509	    this.people.update((ps) => ps.map((p) => (p.id === person.id ? person : p)));
510	  }
511	
512	  /** After a save refused as stale, show the person's current values in the row and the open
513	   *  editor, which then edits that version. */
514	  private async reloadEditing(sheetId: string, id: number): Promise<void> {
515	    try {
516	      const current = await this.api.get(sheetId, id);
517	      if (this.session.sheetId() !== sheetId || this.editingId() !== id) return;
518	      this.taken(current);
519	      this.editingVersion = current.version;
520	      this.form.setValue({ name: current.name, grade: this.gradeOf(current), gradeFrom: this.form.getRawValue().gradeFrom },
521	        { emitEvent: false });
522	    } catch {
523	      // the error shown already says the save was refused
524	    }
525	  }
526	
527	  private reset(): void {
528	    this.editingId.set(null);
529	    this.form.reset({ name: '', grade: 'A', gradeFrom: '' });
530	    this.error.set(null);
531	  }
532	
533	  private async read(sheetId: string): Promise<void> {
534	    const seq = ++this.readSeq;
535	    try {
536	      const [people, claims, rates, periods] = await Promise.all([
537	        this.api.list(sheetId), this.claimsApi.list(sheetId), this.ratesApi.list(sheetId), this.periodsApi.list(sheetId)]);
538	      if (seq === this.readSeq) {
539	        this.rates.set(rates);
540	        this.periods.set(periods);
541	        this.claims.set(claims);
542	        this.people.set(people);
543	      }
544	    } catch {
545	      if (seq === this.readSeq) this.error.set('Something went wrong loading people; try again.');
546	    }
547	  }
548	}
